import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CAKCj7G0.js";const c=JSON.parse('{"title":"HashMap","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/集合/Map/HashMap.md","filePath":"Java/Java/集合/Map/HashMap.md","lastUpdated":1762838572000}'),r={name:"Java/Java/集合/Map/HashMap.md"};function e(n,l,s,h,d,p){return i(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="hashmap" tabindex="-1">HashMap <a class="header-anchor" href="#hashmap" aria-label="Permalink to &quot;HashMap&quot;">​</a></h1><h2 id="一、hashmap-概述" tabindex="-1">一、HashMap 概述 <a class="header-anchor" href="#一、hashmap-概述" aria-label="Permalink to &quot;一、HashMap 概述&quot;">​</a></h2><ul><li><strong>定义</strong>：<code>java.util.HashMap</code> 是 Java 集合框架中最常用的 Map 实现类，基于哈希表实现键值对存储</li><li><strong>继承关系</strong>：继承自 <code>AbstractMap</code>，实现了 <code>Map</code>、<code>Cloneable</code>、<code>Serializable</code> 接口</li><li><strong>核心特点</strong>： <ul><li>非线程安全</li><li>允许 null 键和 null 值（最多一个 null 键）</li><li>无序存储（插入顺序与遍历顺序不一致）</li><li>高效的查询、插入和删除操作，平均时间复杂度为 O(1)</li></ul></li></ul><h2 id="二、底层数据结构" tabindex="-1">二、底层数据结构 <a class="header-anchor" href="#二、底层数据结构" aria-label="Permalink to &quot;二、底层数据结构&quot;">​</a></h2><h3 id="_1-jdk-7-及之前" tabindex="-1">1. JDK 7 及之前 <a class="header-anchor" href="#_1-jdk-7-及之前" aria-label="Permalink to &quot;1. JDK 7 及之前&quot;">​</a></h3><ul><li><strong>数组 + 链表</strong>： <ul><li>数组（Entry 数组，称为桶/bucket）作为主体</li><li>链表解决哈希冲突（拉链法）</li></ul></li></ul><h3 id="_2-jdk-8-及之后" tabindex="-1">2. JDK 8 及之后 <a class="header-anchor" href="#_2-jdk-8-及之后" aria-label="Permalink to &quot;2. JDK 8 及之后&quot;">​</a></h3><ul><li><strong>数组 + 链表 + 红黑树</strong>： <ul><li>数组（Node 数组）作为主体</li><li>链表解决哈希冲突</li><li>当链表长度超过阈值（默认 8）且数组长度≥64时，链表转换为红黑树</li><li>当红黑树节点数量小于阈值（默认 6）时，红黑树转回链表</li></ul></li></ul><h2 id="三、核心参数与构造函数" tabindex="-1">三、核心参数与构造函数 <a class="header-anchor" href="#三、核心参数与构造函数" aria-label="Permalink to &quot;三、核心参数与构造函数&quot;">​</a></h2><h3 id="_1-核心参数" tabindex="-1">1. 核心参数 <a class="header-anchor" href="#_1-核心参数" aria-label="Permalink to &quot;1. 核心参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>DEFAULT_INITIAL_CAPACITY</td><td>16</td><td>默认初始容量（必须是 2 的幂）</td></tr><tr><td>MAXIMUM_CAPACITY</td><td>1&lt;&lt;30</td><td>最大容量</td></tr><tr><td>DEFAULT_LOAD_FACTOR</td><td>0.75f</td><td>默认负载因子</td></tr><tr><td>TREEIFY_THRESHOLD</td><td>8</td><td>链表转红黑树的阈值</td></tr><tr><td>UNTREEIFY_THRESHOLD</td><td>6</td><td>红黑树转链表的阈值</td></tr><tr><td>MIN_TREEIFY_CAPACITY</td><td>64</td><td>树化的最小数组容量</td></tr></tbody></table><h2 id="四、重要方法工作原理" tabindex="-1">四、重要方法工作原理 <a class="header-anchor" href="#四、重要方法工作原理" aria-label="Permalink to &quot;四、重要方法工作原理&quot;">​</a></h2><h3 id="_1-put-方法工作流程" tabindex="-1">1. put 方法工作流程 <a class="header-anchor" href="#_1-put-方法工作流程" aria-label="Permalink to &quot;1. put 方法工作流程&quot;">​</a></h3><p><strong>put 方法</strong>是 HashMap 中最核心的方法之一，用于添加键值对。</p><ol><li><p><strong>计算哈希值</strong>：首先对 key 进行哈希计算，通过对 hashCode() 的返回值进行扰动处理（高16位与低16位异或），以减少哈希冲突。</p></li><li><p><strong>数组初始化检查</strong>：如果内部数组（table）为空或长度为0，则调用 resize() 方法进行初始化。</p></li><li><p><strong>确定存储位置</strong>：通过位运算 <code>(n-1) &amp; hash</code> 计算索引位置（其中 n 是数组长度）。</p></li><li><p><strong>插入节点</strong>：</p><ul><li>如果目标索引位置为空，直接创建新节点并插入。</li><li>如果不为空，需要进一步判断： <ul><li>检查首节点是否与新键相同（哈希值相同且 equals 判断为 true），如果是则替换值。</li><li>如果首节点是红黑树节点，则调用红黑树的插入方法。</li><li>如果是链表节点，则遍历链表： <ul><li>如果找到相同的 key，替换值。</li><li>如果没找到，在链表尾部插入新节点，并检查是否需要将链表转换为红黑树。</li></ul></li></ul></li></ul></li><li><p><strong>扩容检查</strong>：插入完成后，检查元素数量是否超过阈值（capacity * loadFactor），如果超过则进行扩容。</p></li></ol><p><strong>关键点</strong>：</p><ul><li>HashMap 允许替换相同键的值</li><li>插入新节点时会维护 modCount（修改次数）用于快速失败机制</li></ul><h3 id="_2-get-方法工作流程" tabindex="-1">2. get 方法工作流程 <a class="header-anchor" href="#_2-get-方法工作流程" aria-label="Permalink to &quot;2. get 方法工作流程&quot;">​</a></h3><p><strong>get 方法</strong>用于根据键获取对应的值。</p><ol><li><p><strong>哈希计算</strong>：对输入的 key 进行与 put 方法相同的哈希计算。</p></li><li><p><strong>有效性检查</strong>：检查数组是否为空，以及计算出的索引位置是否有节点。</p></li><li><p><strong>查找节点</strong>：</p><ul><li>首先检查索引位置的首节点是否为目标键，如果是则直接返回其值。</li><li>如果不是，根据节点类型继续查找： <ul><li>如果是红黑树节点，调用红黑树的查找方法。</li><li>如果是链表节点，则遍历链表，直到找到对应的键或遍历结束。</li></ul></li></ul></li><li><p><strong>返回结果</strong>：找到则返回对应的值，否则返回 null。</p></li></ol><p><strong>注意</strong>：get 方法返回 null 有两种可能：键不存在，或者键对应的值本身就是 null。可以使用 containsKey() 方法进一步区分。</p><h2 id="扩容机制" tabindex="-1">扩容机制 <a class="header-anchor" href="#扩容机制" aria-label="Permalink to &quot;扩容机制&quot;">​</a></h2><p><strong>resize 方法</strong>是 HashMap 中负责初始化和扩容的关键方法，它具有双重作用：初始化数组和在需要时进行扩容。</p><h3 id="_3-1-数组容量相关参数" tabindex="-1">3.1 数组容量相关参数 <a class="header-anchor" href="#_3-1-数组容量相关参数" aria-label="Permalink to &quot;3.1 数组容量相关参数&quot;">​</a></h3><ul><li><strong>默认初始容量</strong>：16（DEFAULT_INITIAL_CAPACITY）</li><li><strong>最大容量</strong>：2^30（MAXIMUM_CAPACITY = 1&lt;&lt;30），这是 HashMap 数组长度的上限</li><li><strong>容量特性</strong>：始终保持为 2 的幂，这是为了优化哈希计算和扩容时的数据迁移</li></ul><h3 id="_3-2-初始化过程" tabindex="-1">3.2 初始化过程 <a class="header-anchor" href="#_3-2-初始化过程" aria-label="Permalink to &quot;3.2 初始化过程&quot;">​</a></h3><ul><li><strong>初始容量确定</strong>： <ul><li>默认情况下，数组初始长度为 16</li><li>当用户通过构造函数指定初始容量时，HashMap 会将其转换为大于等于该值的最小 2 的幂</li><li>例如：指定 10 会被转换为 16，指定 20 会被转换为 32</li><li>这个转换通过 <code>tableSizeFor()</code> 方法实现</li></ul></li><li><strong>初始阈值计算</strong>： <ul><li>阈值 = 容量 * 负载因子</li><li>默认情况下，初始化时的扩容阈值为 16 * 0.75 = 12</li><li>即当 HashMap 中的键值对总数超过 12 时触发扩容</li></ul></li></ul><h3 id="_3-3-扩容场景" tabindex="-1">3.3 扩容场景 <a class="header-anchor" href="#_3-3-扩容场景" aria-label="Permalink to &quot;3.3 扩容场景&quot;">​</a></h3><ol><li><strong>首次插入元素时</strong>：如果数组尚未初始化，则触发初始化</li><li><strong>元素数量超过阈值时</strong>：当 HashMap 中的键值对总数超过当前阈值（capacity * loadFactor）时触发扩容</li><li><strong>链表树化前的扩容</strong>：当链表长度超过阈值（8）但数组长度不足 64 时，会先触发扩容而不是树化</li></ol><h3 id="_3-4-扩容过程详解" tabindex="-1">3.4 扩容过程详解 <a class="header-anchor" href="#_3-4-扩容过程详解" aria-label="Permalink to &quot;3.4 扩容过程详解&quot;">​</a></h3><ol><li><p><strong>计算新容量</strong>：</p><ul><li>将当前容量扩大为原来的两倍（左移一位，即<code>oldCap &lt;&lt; 1</code>）</li><li>注意：扩容不会超过最大容量限制（2^30）</li></ul></li><li><p><strong>计算新阈值</strong>：</p><ul><li>新阈值通常为新容量乘以负载因子</li><li>如果新容量已达到最大容量，则阈值会被设置为 Integer.MAX_VALUE</li></ul></li><li><p><strong>创建新数组</strong>：使用新容量创建一个新的 Node 数组</p></li><li><p><strong>数据迁移</strong>：将原数组中的元素重新分配到新数组中，这是扩容过程中最复杂的部分。</p></li></ol><h3 id="_3-5-扩容触发条件总结" tabindex="-1">3.5 扩容触发条件总结 <a class="header-anchor" href="#_3-5-扩容触发条件总结" aria-label="Permalink to &quot;3.5 扩容触发条件总结&quot;">​</a></h3><ul><li><strong>数组未初始化时</strong>：首次插入元素时触发初始化</li><li><strong>键值对总数超过阈值时</strong>：当 HashMap 中的键值对总数超过当前阈值（capacity * loadFactor）时触发扩容</li><li><strong>链表过长且数组较小时</strong>：当链表长度超过阈值（8）但数组长度不足 64 时，会触发扩容</li></ul><h4 id="重要说明" tabindex="-1">重要说明 <a class="header-anchor" href="#重要说明" aria-label="Permalink to &quot;重要说明&quot;">​</a></h4><p>链表长度超过阈值但数组长度不足64时的扩容是一种特殊场景。在这种情况下，<strong>即使HashMap中的键值对总数没有超过阈值</strong>，也会触发扩容。这是因为HashMap优先通过扩容来减少哈希冲突，而不是过早地将链表转换为红黑树。只有当数组长度达到64后，才会考虑将长链表转换为红黑树。</p><h3 id="_3-6-数组长度为64时的特殊处理" tabindex="-1">3.6 数组长度为64时的特殊处理 <a class="header-anchor" href="#_3-6-数组长度为64时的特殊处理" aria-label="Permalink to &quot;3.6 数组长度为64时的特殊处理&quot;">​</a></h3><p>当数组长度为64时，HashMap的树化机制会被激活。如果此时某个链表的长度超过阈值8，HashMap不会再进行扩容，而是会将该链表转换为红黑树，以提升查询效率。这是因为：</p><ol><li>数组长度达到64后，继续扩容会消耗更多内存空间</li><li>此时将长链表转换为红黑树比扩容更能有效提升性能</li><li>红黑树的查询时间复杂度为O(log n)，远优于长链表的O(n)</li></ol><h3 id="_3-7-数组长度为64后的扩容机制" tabindex="-1">3.7 数组长度为64后的扩容机制 <a class="header-anchor" href="#_3-7-数组长度为64后的扩容机制" aria-label="Permalink to &quot;3.7 数组长度为64后的扩容机制&quot;">​</a></h3><p>即使数组长度达到64后，HashMap仍会在键值对总数超过阈值时继续进行扩容操作。扩容规则仍然是将容量翻倍：</p><ul><li>64 → 128 → 256 → ...</li><li>扩容会一直进行，直到达到最大容量限制（2^30）</li></ul><p>这种设计的目的是保持较低的负载因子，确保即使在大量数据的情况下，仍能维持良好的查询性能。红黑树的使用仅作为哈希冲突严重时的补充优化，而不是替代正常的扩容机制。</p><h3 id="_3-8-数据迁移策略详解" tabindex="-1">3.8 数据迁移策略详解 <a class="header-anchor" href="#_3-8-数据迁移策略详解" aria-label="Permalink to &quot;3.8 数据迁移策略详解&quot;">​</a></h3><p>在 JDK 8 中，HashMap 针对不同类型的节点采用不同的迁移策略，以提高扩容效率：</p><ul><li><p><strong>单节点迁移</strong>：</p><ul><li>对于链表长度为 1 的节点（没有哈希冲突的情况）</li><li>直接计算其在新数组中的位置并放入</li><li>计算公式：<code>(newCap - 1) &amp; hash</code></li></ul></li><li><p><strong>红黑树节点迁移</strong>：</p><ul><li>对于已经树化的节点，调用 <code>split()</code> 方法进行拆分处理</li><li>拆分过程会将红黑树按照新容量的规则重新分配节点</li><li>如果拆分后树的节点数减少到阈值（6）以下，会将其转换回链表结构</li><li>这样设计可以避免在扩容后维持不必要的树形结构</li></ul></li><li><p><strong>链表节点迁移</strong>：</p><ul><li>JDK 8 采用了一种高效的优化算法，无需重新计算每个节点的哈希值</li><li>使用位运算 <code>(hash &amp; oldCap)</code> 判断节点在扩容后的位置</li><li><strong>位运算原理</strong>：当容量翻倍时，索引计算的掩码增加一位，我们只需检查新增的这一位是 0 还是 1</li><li>迁移规则： <ul><li>如果 <code>(hash &amp; oldCap) == 0</code>：节点保持在原索引位置</li><li>如果 <code>(hash &amp; oldCap) != 0</code>：节点移动到 <code>原索引 + oldCap</code> 的位置</li></ul></li></ul></li><li><p><strong>链表迁移优化的核心原理</strong>：</p><ul><li>由于 HashMap 的容量始终是 2 的幂，扩容时容量翻倍相当于在二进制表示中左移一位</li><li>这导致索引计算的掩码（<code>(n-1) &amp; hash</code>）多了一个高位</li><li>通过检查 hash 值中对应新位的比特值，可以直接判断节点在新数组中的位置</li><li>这种方式避免了重新计算每个节点的完整哈希值，大幅提高了迁移效率</li></ul></li><li><p><strong>迁移效率分析</strong>：</p><ul><li>整个迁移过程的时间复杂度为 O(n)，其中 n 是 HashMap 中的元素总数</li><li>但由于位运算的高效性，实际性能非常好</li><li>在理想哈希分布下，链表会被平均分成两部分，分别迁移到两个新位置</li><li>这种设计确保了扩容后哈希表的负载更加均衡</li></ul></li></ul><h3 id="_3-9-空槽位设计说明" tabindex="-1">3.9 空槽位设计说明 <a class="header-anchor" href="#_3-9-空槽位设计说明" aria-label="Permalink to &quot;3.9 空槽位设计说明&quot;">​</a></h3><p>HashMap在扩容时不是等到数组完全填满（阈值=容量）才扩容，而是在元素数量达到容量的75%时就扩容，这意味着HashMap中<strong>永远会有空槽位</strong>。这是时间效率和空间效率的权衡设计：</p><ul><li>保留空槽位可以显著减少哈希冲突的概率</li><li>降低链表/红黑树的平均长度，保持O(1)的查询效率</li><li>虽然牺牲了一定的空间利用率，但大幅提升了查询、插入和删除的性能</li></ul><h3 id="_3-9-红黑树节点出现的可能性" tabindex="-1">3.9 红黑树节点出现的可能性 <a class="header-anchor" href="#_3-9-红黑树节点出现的可能性" aria-label="Permalink to &quot;3.9 红黑树节点出现的可能性&quot;">​</a></h3><p>在实际应用中，<strong>红黑树节点确实很少被用到</strong>，这主要有以下原因：</p><ol><li><p><strong>泊松分布原理</strong>：根据统计学中的泊松分布，当负载因子为0.75时，链表长度达到8的概率约为0.00000006（百万分之0.06），几乎可以忽略不计。这是Java开发者精心选择参数的结果。</p></li><li><p><strong>双重条件限制</strong>：树化需要同时满足两个条件：</p><ul><li>链表长度超过阈值8</li><li>数组长度≥64 如果数组长度不足64，即使链表长度超过8，也只会触发扩容而不是树化。</li></ul></li><li><p><strong>扩容频繁发生</strong>：由于HashMap在元素数量达到容量75%时就扩容，且扩容后容量翻倍，这使得链表很难达到足够长的长度。</p></li><li><p><strong>正常哈希分布</strong>：对于实现良好的hashCode()方法，键的分布通常比较均匀，链表长度很少会达到树化阈值。</p></li></ol><p><strong>实际场景</strong>：只有在极特殊情况下（如严重的哈希冲突、恶意构造的键值对），红黑树才会真正派上用场，这也是为什么Java 8引入红黑树主要是为了防止潜在的DoS攻击，而不是提高常规使用场景的性能。</p><h3 id="_3-10-扩容的影响" tabindex="-1">3.10 扩容的影响 <a class="header-anchor" href="#_3-10-扩容的影响" aria-label="Permalink to &quot;3.10 扩容的影响&quot;">​</a></h3><ul><li>扩容是一个比较耗时的操作，可能会导致性能波动</li><li>合理设置初始容量可以减少扩容次数，提高性能</li></ul><h2 id="五、关键优化技术" tabindex="-1">五、关键优化技术 <a class="header-anchor" href="#五、关键优化技术" aria-label="Permalink to &quot;五、关键优化技术&quot;">​</a></h2><ol><li><p><strong>哈希计算优化</strong>：</p><ul><li>通过高16位与低16位异或运算，让高位参与到哈希计算中，减少哈希冲突</li><li>这一设计在数组容量较小时尤为重要</li></ul></li><li><p><strong>索引计算优化</strong>：</p><ul><li>使用位运算 <code>(n - 1) &amp; hash</code> 代替取模运算，提高计算效率</li><li>这也是要求容量必须为 2 的幂的主要原因</li></ul></li><li><p><strong>树化机制</strong>：</p><ul><li>当链表过长时（默认长度≥8），将链表转换为红黑树</li><li>大幅提升查询效率，从 O(n) 优化到 O(log n)</li><li>当红黑树节点减少到一定数量（默认≤6）时，会转回链表</li></ul></li><li><p><strong>红黑树自平衡机制</strong>：</p><ul><li>红黑树节点的比较<strong>顺序</strong>： <ul><li>首先比较节点的哈希值（hashCode）</li><li>只有当哈希值相同时，才会比较键（key）</li><li>键的比较优先级：先尝试使用Comparable接口进行自然排序，如果键未实现该接口，则使用System.identityHashCode()基于对象内存地址进行比较</li></ul></li><li>确保树的平衡性，维持O(log n)的查询效率</li><li>在扩容时会通过split()方法重新分配节点并可能转回链表</li></ul></li><li><p><strong>扩容优化</strong>：</p><ul><li>JDK 8 使用位运算快速判断元素在扩容后的位置</li><li>采用尾插法，避免链表反转问题</li></ul></li></ol><h2 id="六、线程安全问题" tabindex="-1">六、线程安全问题 <a class="header-anchor" href="#六、线程安全问题" aria-label="Permalink to &quot;六、线程安全问题&quot;">​</a></h2><h3 id="_1-jdk-7-中的死循环问题" tabindex="-1">1. JDK 7 中的死循环问题 <a class="header-anchor" href="#_1-jdk-7-中的死循环问题" aria-label="Permalink to &quot;1. JDK 7 中的死循环问题&quot;">​</a></h3><p>在 JDK 7 中，多线程并发扩容时可能导致链表形成环，从而引发死循环。主要原因是：</p><ul><li>采用头插法插入节点</li><li>并发扩容时，多个线程同时修改链表结构</li><li>导致链表节点之间的引用关系混乱，形成环</li></ul><h3 id="_2-jdk-8-中的数据覆盖问题" tabindex="-1">2. JDK 8 中的数据覆盖问题 <a class="header-anchor" href="#_2-jdk-8-中的数据覆盖问题" aria-label="Permalink to &quot;2. JDK 8 中的数据覆盖问题&quot;">​</a></h3><p>虽然 JDK 8 修复了死循环问题，但仍存在数据覆盖的风险：</p><ul><li>缺乏同步机制，多线程同时操作可能导致数据覆盖</li><li>例如，两个线程同时检测到同一个位置为空并插入数据</li></ul><h3 id="_3-解决方案" tabindex="-1">3. 解决方案 <a class="header-anchor" href="#_3-解决方案" aria-label="Permalink to &quot;3. 解决方案&quot;">​</a></h3><p>在多线程环境中使用 HashMap 时，推荐以下替代方案：</p><ul><li>使用 <code>ConcurrentHashMap</code>：专为并发设计，性能更好</li><li>使用 <code>Collections.synchronizedMap()</code>：包装现有 HashMap</li><li>使用显式锁（如 ReentrantLock）保护 HashMap 操作</li></ul><h2 id="七、使用注意事项" tabindex="-1">七、使用注意事项 <a class="header-anchor" href="#七、使用注意事项" aria-label="Permalink to &quot;七、使用注意事项&quot;">​</a></h2><ol><li><p><strong>键的设计原则</strong>：</p><ul><li>作为键的对象必须重写 <code>equals()</code> 和 <code>hashCode()</code> 方法</li><li>这两个方法的实现必须保持一致：如果两个对象 equals 返回 true，它们的 hashCode 必须相等</li><li>推荐使用不可变对象作为键（如 String、Integer），避免键的值改变导致无法正确查找</li></ul></li><li><p><strong>初始容量设置</strong>：</p><ul><li>如果可以预估存储的元素数量，建议设置合适的初始容量</li><li>计算公式：初始容量 = 期望元素数量 / 负载因子</li><li>合理设置初始容量可以减少扩容次数，提高性能</li></ul></li><li><p><strong>遍历方式选择</strong>：</p><ul><li>推荐使用 <code>entrySet()</code> 遍历键值对，比 <code>keySet()</code> 更高效</li><li>Java 8 及以上版本，推荐使用 <code>forEach()</code> 方法配合 Lambda 表达式</li></ul></li><li><p><strong>null 值处理</strong>：</p><ul><li>HashMap 允许 null 键和 null 值，但需要注意处理</li><li>调用 <code>get(key)</code> 返回 null 时，无法直接判断是键不存在还是值为 null</li><li>可以使用 <code>containsKey(key)</code> 方法进一步确认键是否存在</li></ul></li></ol><h2 id="八、常见问题解答" tabindex="-1">八、常见问题解答 <a class="header-anchor" href="#八、常见问题解答" aria-label="Permalink to &quot;八、常见问题解答&quot;">​</a></h2><ol><li><p><strong>为什么 HashMap 的容量必须是 2 的幂？</strong></p><ul><li>位运算效率更高：可以使用 <code>(n-1) &amp; hash</code> 代替取模运算</li><li>扩容时元素分配更均匀：使用位运算可以高效地将元素分配到原位置或新位置</li></ul></li><li><p><strong>为什么负载因子默认是 0.75？</strong></p><ul><li>这是空间利用率和查询性能的平衡点</li><li>过低会浪费空间，过高会增加哈希冲突概率</li><li>经过大量实践验证，0.75 是一个合理的折衷值</li></ul></li><li><p><strong>HashMap 如何处理 null 键？</strong></p><ul><li>null 键的哈希值被固定为 0</li><li>始终存储在数组索引为 0 的位置</li><li>由于只能有一个 null 键，后续插入的 null 键会覆盖之前的值</li></ul></li><li><p><strong>为什么 JDK 8 引入红黑树？</strong></p><ul><li>当哈希冲突严重时，链表会变得很长</li><li>长链表会导致查询效率下降到 O(n)</li><li>红黑树可以将查询效率优化到 O(log n)</li></ul></li><li><p><strong>HashMap、LinkedHashMap、TreeMap 的主要区别？</strong></p><ul><li>HashMap：无序，查询效率高，基于哈希表</li><li>LinkedHashMap：保持插入或访问顺序，通过双向链表维护顺序</li><li>TreeMap：按键排序，查询和插入时间复杂度为 O(log n)，基于红黑树</li></ul></li></ol>',70)])])}const g=a(r,[["render",e]]);export{c as __pageData,g as default};
